    public string StrHelpShowReferenceError { get; set; } = "Draws two lines from the comet to its reference orbit (the red track):\n• cross-track: to the closest point of the track;\n• same-epoch: to where the reference says the comet should be now.\n\nEach line is shown only while it is longer than 10 nucleus radii.";
    public string StrHelpDustVisibility { get; set; } = "Display stretch of the dust: the softening of an asinh curve over the accumulated optical depth, relative to the brightest dust in view (it adapts to the view like an eye). From 0.00001 to 1, on a logarithmic scale.\n\nSmaller: the faint, old tail and trail (thousands of times fainter than the coma) become visible while the coma saturates.\n1: close to linear, physically proportional brightness.\n\nVisual only: the simulated dust is unchanged.";
    public string StrHelpDustFlow { get; set; } = "Brightness marks riding the dust along synchrones (the dust of one emission instant), a motion cue near the nucleus: peak 4×, trough 0.15×, mean 1.\n\nOff by default: seen from 0.03 AU and beyond, the marks are the synchrone fan itself, hard rays through the nucleus that the physical optical depth does not show.\n\nVisual only. Their speed is set by the flow time-lapse.";
    public string StrHelpDustRhoNorm { get; set; } = "Divides the dust brightness by the distance from the nucleus (ρ), so the bright inner coma and the faint outer jets share one exposure.\n\nDisplay only: the simulated dust is unchanged. On by default.";
    public string StrHelpDustTrajectories { get; set; } = "Draws as lines the paths of about 200 grains since they left the nucleus, one colour per jet.";
    public string StrHelpDustExposure { get; set; } = "Brightens (+) or darkens (−) the dust over the automatic exposure, in photographic stops (EV), from −6 to +6 in steps of 0.25. One stop doubles or halves the brightness.";
    public string StrHelpDustTracers { get; set; } = "Draws one dust cluster in 256 as bright dots at the exact positions of its grain sizes, from the slow large grains to the fast small ones: the dots span the tail.\n\nThe dust drifts at 2 to 150 m/s while a pixel of a wide view spans tens of km: at low simulation speed it moves far less than a pixel per second, and the dense dots blend into a still fog. Tracers are real particles to follow (raise the simulation speed to see them stream).\n\nVisual only.";
    public string StrHelpDustFlowSpeed { get; set; } = "Speed of the brightness marks (flow pulses) that ride the dust while the simulation runs; they freeze on pause. From 1 to 10000, on a logarithmic scale.\n\n1: the marks move exactly with the dust (its real speed on screen, often far below a pixel per second in wide views).\nK: every mark moves K times faster than its dust, in its direction, so the whole swarm keeps its true velocity field at a readable pace. Changing it never jumps the marks.\n\nVisual only.";
    public string StrHelpGizmo { get; set; } = "The wireframe sphere and axes around the nucleus. Saved with the file.\n\nThe boxes below choose its parts:\n• Grid: the latitude / longitude wireframe;\n• Body X/Y: the body-fixed X (red) and Y (green) axes, rotating with the nucleus;\n• Spin axis: the rotation axis (body Z, blue);\n• Sun: the arrow towards the Sun;\n• Velocity: the comet's heliocentric velocity direction (magenta).";
    public string StrHelpJetAngles { get; set; } = "Draws the selected jet's latitude and longitude in the viewport as arcs, with their values in degrees. Saved with the file.";
    public string StrHelpJetLatitude { get; set; } = "Latitude of the jet source on the nucleus, in degrees in the body-fixed frame: +90 is the north spin pole, 0 the equator, −90 the south pole.";
    public string StrHelpJetLongitude { get; set; } = "Longitude of the jet source on the nucleus, in degrees from the prime meridian (−180 to 180). The nucleus spin carries the jet around as it rotates.";
    public string StrHelpJetStreamColor { get; set; } = "Colour used to draw this jet in the viewport (its dust and direction line).\n\nDisplay only: it does not change the physics.";
    public string StrHelpJetBeta { get; set; } = "Computed, read-only. β is the ratio of the solar radiation-pressure force to solar gravity on a grain: β ≈ 0.57 · Q_pr / (ρ · s), with ρ the density in g/cm³ and s the grain radius in µm.\n\nβ ∝ 1/s: small grains have a larger β and curve away from the Sun faster.\n\nThe box shows β of the reference grain, whose diameter is the geometric mean of the smallest and largest diameter. The β range next to it spans the simulated grain sizes: the smallest β is the largest grain's, the largest β the smallest grain's.";
    public string StrHelpJetQDust { get; set; } = "Computed, read-only. The dust mass production rate at 1 AU from the Sun, in kg/s, as the engine applies it: this jet's Q_d at 1 AU clamped to the model-wide max (Q_d max).";
    public string StrHelpJetDensity { get; set; } = "Bulk density of this jet's grains, in g/cm³ (cometary dust about 0.5 to 1). It enters β and the dust mass a given brightness needs.";
    public string StrHelpJetQpr { get; set; } = "Radiation-pressure efficiency Q_pr of this jet's grains (0.5 to 2; 1 is a grey body). It scales β only, not the brightness.";
    public string StrHelpJetAlbedo { get; set; } = "Geometric albedo of this jet's dust (0.01 to 0.5; cometary dust 0.03 to 0.06). It scales the brightness only; the amount of dust is the jet's production rate Q_d.";
    public string StrHelpJetSizeQ { get; set; } = "Exponent q of this jet's grain size law n(d) ∝ d^−q over the simulated diameters (2 to 5; 3.5 is the usual value). A larger q means more small grains.\n\nWhich q the dust uses depends on \"Orbit-dependent size distribution\" (Advanced: dynamic model):\nOff: the continuous dust uses q = 3.5. This q only sets the single grains drawn close to the camera, which are off by default.\nOn: the continuous dust uses this q. If the q(t) table has rows, it uses the table instead: q is interpolated linearly in days from perihelion and held constant outside the table.";
    public string StrHelpJetGrain { get; set; } = "This jet's own dust grains: every jet has its own, and a new jet starts from \"Defaults for new jets\" further down.\n\nSimulated grains have diameters d from the smallest to the largest, with number density n(d) ∝ d^−q (default 10-1000 µm, q = 3.5).\n\nThe grain size, density and Q_pr set β ∝ Q_pr/(ρ·s), how hard sunlight pushes the grains away from the Sun. The albedo sets how bright they are; the amount of dust is the jet's production rate Q_d (Advanced: activity).\n\nWhich q the continuous dust uses: with \"Orbit-dependent size distribution\" (Advanced: dynamic model) off, q = 3.5 whatever this jet's q. On, this jet's q, or its q(t) table interpolated linearly in days from perihelion and held constant outside it.\n\nEach field has its own ? with its range.";
    public string StrHelpJetActivity { get; set; } = "This jet's dust mass production rate Q_d at 1 AU from the Sun, in kg/s: how much dust it produces. The jets add up: the comet's total is the Σ read-out under Advanced: activity (Q_d) in the defaults.\n\nQ_d(r) = min(max, Q_d₀ · r^−k), zero beyond the cutoff; the exponent k, the cutoff and the max are shared by every jet (Advanced: activity (Q_d) under Defaults for new jets).\n\nQ_d does not depend on the grain (density, size, albedo) or the speed: those set the brightness and β only.\n\nComets range from well under 1 kg/s to thousands of kg/s.";
    public string StrHelpJetDustRate0 { get; set; } = "This jet's dust mass production rate at 1 AU from the Sun, in kg/s. It scales as r_h^−k up to the max and stops beyond the cutoff (both shared by every jet).\n\nComets range from well under 1 kg/s to thousands of kg/s.";
    public string StrHelpCopyGrain { get; set; } = "Gives every other jet this jet's grain and activity: smallest and largest diameter, density, Q_pr, albedo, q and Q_d₀, and its dynamic model: the insolation and orbit-dependent size law toggles, the pre-start source, the dust lifetime and the q table.\n\nTheir sites, speeds and colours stay as they are.";
    public string StrHelpJetDefaults { get; set; } = "Every jet has its own grain (smallest and largest diameter, density, Q_pr, albedo, q) and its own Q_d₀: edit them in the selected jet's Grain and Activity panels.\n\nThe values here are what a newly added jet starts from; changing them does not change existing jets. Only the shape of the Q_d law (exponent, cutoff, max, under Advanced: activity) is shared by every jet.";
    public string StrHelpDustDensity { get; set; } = "Bulk density of the grains of new jets, in g/cm³ (cometary dust about 0.5 to 1). It enters β and the dust mass a given brightness needs.\n\nEach jet then has its own (its Grain panel).";
    public string StrHelpScatteringEfficiency { get; set; } = "Radiation-pressure efficiency Q_pr of new jets' grains (0.5 to 2; 1 is a grey body). It scales β only, not the brightness.\n\nEach jet then has its own (its Grain panel).";
    public string StrHelpDustAlbedo { get; set; } = "Geometric albedo of new jets' dust (0.01 to 0.5; cometary dust 0.03 to 0.06). It scales the brightness only, not the production rate Q_d.\n\nEach jet then has its own (its Grain panel).";
    public string StrHelpActivity { get; set; } = "Q_d is the dust mass production rate: how much dust (kg/s) the comet produces at each distance from the Sun.\n\nQ_d(r) = min(max, Q_d₀ · r^−k), zero beyond the cutoff.\n• Q_d at 1 AU: the rate at 1 AU (kg/s), per jet; the value here is the default for new jets.\n• Exponent k: how fast the rate falls with solar distance (k = 2: twice as far → 4× less dust).\n• Cutoff: distance where the emission stops.\n• Max: cap on the rate close to the Sun.\nk, cutoff and max are shared by every jet.\n\nThe Σ line at the top is the comet's total activity: the jets' rates Q_d add up. It is shown at 1 AU from the Sun and, with a committed comet, at its current distance.\n\nQ_d sets the amount of dust directly: it does not depend on the grain or the speed. Density, diameter and albedo set how bright that dust is and how hard radiation pressure pushes the grains (β ∝ 1/(ρ·s)), i.e. how much the coma curves away from the Sun.";
    public string StrHelpDustRate0 { get; set; } = "Default dust mass production rate at 1 AU from the Sun for new jets, in kg/s. It scales as r_h^−k up to the max and stops beyond the cutoff.\n\nEach jet then has its own (its Activity panel).";
    public string StrHelpDustRatePower { get; set; } = "Exponent k of the production law Q_d(r) = Q_d₀ · r^−k, with r the distance from the Sun in AU (1 to 4). 2 is the classic value; a larger k means the rate drops faster as the comet recedes.\n\nShared by every jet.";
    public string StrHelpDustRateCutoff { get; set; } = "Distance from the Sun, in AU (3 to 100), beyond which the comet emits no dust.\n\nShared by every jet.";
    public string StrHelpDustRateMax { get; set; } = "Upper limit on each jet's dust production rate, in kg/s, so that the emission does not grow without bound close to the Sun.\n\nShared by every jet.";
    public string StrHelpSizeDistribution { get; set; } = "The size law exponent q that new jets start from (2 to 5; 3.5 is the usual value). Changing it does not change existing jets: each jet has its own q in its Grain panel.\n\nSimulated grains have diameters d from the smallest to the largest, with number density n(d) ∝ d^−q. A larger q means more small grains.\n\nA jet's q reaches its continuous dust only with the jet's \"Orbit-dependent size distribution\" on. Off, the continuous dust uses q = 3.5.";
    public string StrHelpHeaderJetDynamics { get; set; } = "Dynamic model";
    public string StrHelpJetDynamics { get; set; } = "How this jet's emission evolves in time. The two toggles are off and the lifetime is 30 days for every jet of an older save, which keeps its dust exactly as it was; changing any value here invalidates the simulation (commit again).";
    public string StrHelpHeaderJetInsolation { get; set; } = "Insolation-weighted emission";
    public string StrHelpJetInsolation { get; set; } = "Off: the site emits at the full rate Q_d whenever the Sun is above its horizon and nothing at night (on/off gating).\n\nOn: the rate is Q_d · cos i, with i the solar incidence angle at the site, integrated in closed form over the spin; the emitted mass is lower (equal only at normal incidence) and the grains are released more densely around local noon.";
    public string StrHelpHeaderJetOrbitSizeLaw { get; set; } = "Orbit-dependent size distribution";
    public string StrHelpJetOrbitSizeLaw { get; set; } = "Off: the continuous dust uses q = 3.5 as before.\n\nOn: the dust emitted in each window uses this jet's own q, or, with rows in the table below, the q interpolated at the window's time from perihelion.";
    public string StrHelpHeaderJetSpkBeforeStart { get; set; } = "Pre-start dust from the ephemeris";
    public string StrHelpJetSpkBeforeStart { get; set; } = "The jets ignite a lead time before the start epoch (Comet tab, Dust lead time).\n\nOn: that pre-start dust is emitted from the comet's ephemeris (SPK) where the file covers those dates; the commit downloads the SPK from start − lead. Off: it is emitted from the reference orbit, as older saves do.";
    public string StrHelpHeaderJetLifetime { get; set; } = "Dust lifetime";
    public string StrHelpJetLifetime { get; set; } = "How long a grain is kept after emission, 1 to 365 days (30 by default).\n\nThe dust is emitted in three age tiers, each on a grid of 256 windows over its age band (0–1, 1–8 and 8–64 lifetimes); the emission steps shown are the band lengths divided by 256. The Dust lead time in the Comet tab cannot exceed the longest lifetime among the jets.";
    public string StrHelpHeaderJetSizeQTable { get; set; } = "q along the orbit";
    public string StrHelpJetSizeQTable { get; set; } = "Up to 8 rows of (days from perihelion, q), q from 0 to 6. The q of an emission window is interpolated linearly between the rows and held at the end values outside them; one row is a constant q; no row means this jet's own q.\n\nNegative days are before perihelion.";
